  "implementation": "def solve(case):
    payload = case['payload']
    nodes_raw = payload['nodes']
    required_symbols = set(payload['required_symbols'])

    # Build node map and tree
    id_to_node = {}
    for n in nodes_raw:
        nid = n['id']
        id_to_node[nid] = {
            'id': nid,
            'parent': n['parent'],
            'symbol': n['symbol'],
            'depth': n['depth'],
            'removable': n['removable'],
            'utility': n['utility'],
            'children': []
        }

    # Validate and build children lists
    root_id = None
    for nid, node in id_to_node.items():
        parent_id = node['parent']
        if parent_id is None:
            if root_id is not None:
                raise ValueError('Multiple roots')
            root_id = nid
        else:
            if parent_id not in id_to_node:
                raise ValueError(f'Parent {parent_id} not found for node {nid}')
            id_to_node[parent_id]['children'].append(nid)
    if root_id is None:
        raise ValueError('No root node')

    # Precompute subtree nodes (including self)
    subtree_nodes = {}
    def dfs(nid):
        nodes = {nid}
        for child in id_to_node[nid]['children']:
            nodes |= dfs(child)
        subtree_nodes[nid] = nodes
        return nodes
    dfs(root_id)

    # Initial retained set
    retained = set(id_to_node.keys())
    removed = set()
    removal_order = []

    # Build candidate list (removable, not required symbol, not root)
    candidates = []
    for nid, node in id_to_node.items():
        if node['removable'] and node['symbol'] not in required_symbols and nid != root_id:
            candidates.append((node['depth'], nid))
    # Sort by depth descending, then by node ID string ascending
    candidates.sort(key=lambda x: (-x[0], x[1]))

    for depth, nid in candidates:
        if nid in removed:
            continue
        node = id_to_node[nid]
        # Check no retained children
        has_retained_child = any(child not in removed for child in node['children'])
        if has_retained_child:
            continue
        # Check that required symbols still exist after removal
        # Compute symbols in retained nodes outside this subtree
        sub_nodes = subtree_nodes[nid]
        remaining_symbols = set()
        for rnid in retained:
            if rnid not in sub_nodes:
                remaining_symbols.add(id_to_node[rnid]['symbol'])
        if not required_symbols.issubset(remaining_symbols):
            continue
        # Remove this node and its subtree
        removal_order.append(nid)
        removed |= sub_nodes
        retained -= sub_nodes

    # Validate that all required symbols are still present
    retained_symbols = {id_to_node[rnid]['symbol'] for rnid in retained}
    if not required_symbols.issubset(retained_symbols):
        raise ValueError('Infeasible: required symbols lost after reduction')

    retained_ids = sorted(retained)
    return {'retained_ids': retained_ids, 'removal_order': removal_order}"
}
